end
function out=unpack_packed_field(f,b)
if ~isempty(f.terminal)
 recsize=0;sizes=zeros(numel(f.terminal),1);for z=1:numel(f.terminal),term=f.terminal{z};sizes(z)=type_size(term.type)*max(1,prod(term.dims));recsize=recsize+sizes(z);end
 if recsize==0||mod(numel(b),recsize),error('SDL:Malformed','invalid packed struct payload length');end
 n=numel(b)/recsize;records=reshape(uint8(b(:)),recsize,n);out=struct();pos=1;
 for z=1:numel(f.terminal)
  term=f.terminal{z};sz=sizes(z);column_bytes=records(pos:pos+sz-1,:);
  shape=[fliplr(term.dims),n];if isempty(term.dims),shape=[n,1];end
  out=set_path(out,term.path,reshape(unpack_packed(term.type,column_bytes(:),term.enum),shape));pos=pos+sz;
 end
else
 sz=type_size(f.type);if isempty(sz)||mod(numel(b),sz),error('SDL:Malformed','invalid packed payload length');end
 count=numel(b)/sz;column_bytes=reshape(b,sz,count);out=unpack_packed(f.type,column_bytes,f.enum);
end
end
function values=unpack_packed(t,columns,is_enum)
sz=type_size(t);if is_enum,t='int32';end
if host_little()
 if any(strcmp(t,{'c32','c64'})),unit=sz/2;else,unit=sz;end
 if unit>1,columns=reshape(columns,unit,[]);columns=flipud(columns);columns=columns(:);end
end
if strcmp(t,'bool')
 if any(columns(:)>1),error('SDL:Malformed','invalid packed bool value');end;values=logical(columns(:));
elseif any(strcmp(t,{'c32','c64'}))
 if strcmp(t,'c32'),raw=typecast(uint8(columns(:)),'single');else,raw=typecast(uint8(columns(:)),'double');end
 components=reshape(raw,2,[]);values=complex(components(1,:),components(2,:)).';
else
 if strcmp(t,'fl32'),values=typecast(uint8(columns(:)),'single');elseif strcmp(t,'fl64'),values=typecast(uint8(columns(:)),'double');else,values=typecast(uint8(columns(:)),t);end;values=values(:);
end
end
function s=set_path(s,path,value)
parts=strsplit(path,'.');if numel(parts)==1,s.(parts{1})=value;else,if ~isfield(s,parts{1}),s.(parts{1})=struct();end;s.(parts{1})=set_path(s.(parts{1}),strjoin(parts(2:end),'.'),value);end
end
function yes=exact_type(ctx,name,active)
if ~isKey(ctx.messages,name),yes=true;return;end
if isKey(ctx.exact_cache,name),yes=ctx.exact_cache(name);return;end
if ~ctx.exact(name)||any(strcmp(active,name)),yes=false;ctx.exact_cache(name)=false;return;end
active{end+1}=name;fields=ctx.messages(name);yes=true;for k=1:numel(fields),if ~exact_type(ctx,fields{k}.type,active),yes=false;break;end,end
ctx.exact_cache(name)=yes;
end
function [value,pos]=read_message(ctx,name,data,pos,depth,skip)
if depth>64,error('SDL:Malformed','nesting too deep');end
if ~skip&&~isKey(ctx.local,name),error('SDL:SchemaMismatch','unknown local message');end
if ~skip&&ctx.fixed_codecs(name)
 n=ctx.sizes(name);if n>numel(data)-pos+1,error('SDL:Malformed','truncated fixed record');end
 value=feval(ctx.functions(name),'decode_fixed',ctx,data(pos:pos+n-1));pos=pos+n;return
end
fields=ctx.messages(name);binding=ctx.bindings(name);local={};value=[];if ~skip,local=ctx.local(name);value=feval(ctx.functions(name),'new');end
for k=1:numel(fields)
 f=fields{k};n=1;if ~strcmp(f.modifier,'required'),[n,pos]=read_count(data,pos);end
 if strcmp(f.modifier,'optional')&&n>1,error('SDL:Malformed','optional count exceeds one');end
 size=fixed_size(ctx,f.type,{},0);if size>0,unit=size*prod(f.dims);if n>floor((numel(data)-pos+1)/unit),error('SDL:Malformed','truncated array');end
 elseif n>1048576,error('SDL:Malformed','variable sequence too large');end
 discard=skip||binding(k)==0;
 if any(strcmp(f.modifier,{'packed','repeated'}))
  l=[];if ~discard,l=local{binding(k)};end
  if ~discard&&strcmp(l.modifier,'packed')&&exact_type(ctx,f.type,{})
   bytes=size*n;if pos+bytes-1>numel(data),error('SDL:Malformed','truncated packed array');end
   if ctx.mex&&isempty(l.terminal)&&strcmp(f.type,'c32')
    x=sdl_packed_mex('decode_c32',data,double(pos),double(n));
   else,x=unpack_packed_field(l,data(pos:pos+bytes-1));end
   validate_packed_enums(ctx,l,x);pos=pos+bytes;value.(l.name)=x;
  elseif ~discard&&ctx.fixed_enabled&&strcmp(l.modifier,'repeated')&&isempty(f.dims)&&~isKey(ctx.messages,f.type)&&size>0
   bytes=size*n;x=sdl_matlab_runtime('unpack_fixed',ctx,f.type,data(pos:pos+bytes-1),isKey(ctx.enums,f.type));
   value.(l.name)=num2cell(x);pos=pos+bytes;
  else
   items=cell(n,1);for j=1:n,[items{j},pos]=read_value(ctx,f.type,f.dims,data,pos,depth+1,discard);end
   if ~discard
    if strcmp(l.modifier,'packed')
     if isempty(l.terminal),if n==0,x=unpack_packed_field(l,uint8([]));else,x=vertcat(items{:});end
     else,x=struct();for z=1:numel(l.terminal),term=l.terminal{z};values=cell(n,1);for j=1:n,values{j}=packed_get_path(items{j},term.path);end
       if n==0,vals=[];else,vals=cat(numel(term.dims)+1,values{:});end
       if isempty(term.dims),vals=vals(:);end;x=set_path(x,term.path,vals);
      end
     end
     value.(l.name)=x;
    else,value.(l.name)=items;end
   end
  end
 elseif n==1
  [x,pos]=read_value(ctx,f.type,f.dims,data,pos,depth+1,discard);if ~discard,l=local{binding(k)};value.(l.name)=x;end
 elseif ~discard,l=local{binding(k)};value.(l.name)=[];
 end
end
end
function [value,pos]=read_value(ctx,type,dims,data,pos,depth,skip)
if depth>64,error('SDL:Malformed','nesting too deep');end
if ~isempty(dims)
 n=prod(dims);items=cell(n,1);for k=1:n,[items{k},pos]=read_value(ctx,type,[],data,pos,depth+1,skip);end
 if skip,value=[];else,shape=fliplr(dims);if numel(shape)==1,shape=[shape 1];end;value=reshape([items{:}],shape);end;return
end
if isKey(ctx.messages,type),[value,pos]=read_message(ctx,type,data,pos,depth+1,skip);return;end
if strcmp(type,'string'),[n,pos]=read_count(data,pos);if n>numel(data)-pos+1,error('SDL:Malformed','truncated string');end
 b=data(pos:pos+n-1);valid_utf8(b);pos=pos+n;if skip,value=[];elseif isempty(b),value='';else,value=native2unicode(b(:)','UTF-8');end;return
end
is_enum=isKey(ctx.enums,type);if is_enum,n=4;else,n=primitive_size(type);end
if n==0||n>numel(data)-pos+1,error('SDL:Malformed','truncated scalar');end;b=data(pos:pos+n-1);pos=pos+n;
value=unpack_packed(type,b,is_enum);
if is_enum,e=ctx.enums(type);if ~ismember(value,e.values),error('SDL:InvalidEnum','invalid sender enum');end
 if ~skip&&isKey(ctx.functions,type),local=feval(ctx.functions(type));if ~ismember(value,cell2mat(struct2cell(local))),error('SDL:InvalidEnum','invalid local enum');end,end
end
if skip,value=[];end
end
function n=primitive_size(t)
switch t
case {'bool','int8','uint8'},n=1;case {'int16','uint16'},n=2;case {'int32','uint32','fl32'},n=4;
case {'int64','uint64','fl64','c32'},n=8;case 'c64',n=16;otherwise,n=0;
end
end
function n=type_size(t),n=primitive_size(t);if n==0&&~strcmp(t,'string'),n=4;end,end
function yes=host_little(),[~,~,order]=computer;yes=strcmp(order,'L');end
function valid_utf8(b)
b=double(b(:));if all(b<128),return;end
p=1;while p<=numel(b)
 x=b(p);p=p+1;if x<128,continue;end
 if x>=194&&x<=223,n=1;v=mod(x,32);minimum=128;
 elseif x>=224&&x<=239,n=2;v=mod(x,16);minimum=2048;
 elseif x>=240&&x<=244,n=3;v=mod(x,8);minimum=65536;
 else,error('SDL:Malformed','invalid UTF-8');end
 if n>numel(b)-p+1,error('SDL:Malformed','truncated UTF-8');end
 for j=1:n,y=b(p);p=p+1;if y<128||y>191,error('SDL:Malformed','invalid UTF-8 continuation');end;v=v*64+mod(y,64);end
 if v<minimum||v>1114111||(v>=55296&&v<=57343),error('SDL:Malformed','invalid UTF-8 scalar');end
end
end

function yes=records_native(v)
yes=false;
try
 r=v.records;p=r.pose;
 yes=isa(r.id,'int32')&&isa(p.position.values,'single')&&isa(p.rotation,'single')&&isa(r.measures,'single');
catch
end
end

% First 32 SHA-256 bits. uint32 addition saturates, so sum in uint64 and mask.
function id=catalogue_hash(data)
k=uint32(hex2dec(char('428a2f98','71374491','b5c0fbcf','e9b5dba5','3956c25b','59f111f1','923f82a4','ab1c5ed5','d807aa98','12835b01','243185be','550c7dc3','72be5d74','80deb1fe','9bdc06a7','c19bf174','e49b69c1','efbe4786','0fc19dc6','240ca1cc','2de92c6f','4a7484aa','5cb0a9dc','76f988da','983e5152','a831c66d','b00327c8','bf597fc7','c6e00bf3','d5a79147','06ca6351','14292967','27b70a85','2e1b2138','4d2c6dfc','53380d13','650a7354','766a0abb','81c2c92e','92722c85','a2bfe8a1','a81a664b','c24b8b70','c76c51a3','d192e819','d6990624','f40e3585','106aa070','19a4c116','1e376c08','2748774c','34b0bcb5','391c0cb3','4ed8aa4a','5b9cca4f','682e6ff3','748f82ee','78a5636f','84c87814','8cc70208','90befffa','a4506ceb','bef9a3f7','c67178f2')));
h=uint32(hex2dec(char('6a09e667','bb67ae85','3c6ef372','a54ff53a','510e527f','9b05688c','1f83d9ab','5be0cd19')));
data=uint8(data(:));bits=uint64(numel(data))*uint64(8);
data=[data;uint8(128);zeros(mod(56-mod(numel(data)+1,64),64),1,'uint8')];
for j=7:-1:0,data(end+1)=uint8(bitand(bitshift(bits,-8*j),uint64(255)));end
for offset=1:64:numel(data)
 w=zeros(64,1,'uint32');
 for i=1:16,p=offset+4*(i-1);w(i)=bitor(bitor(bitshift(uint32(data(p)),24),bitshift(uint32(data(p+1)),16)),bitor(bitshift(uint32(data(p+2)),8),uint32(data(p+3))));end
 for i=17:64
  x=w(i-15);y=w(i-2);
  s0=bitxor(bitxor(cat_rotr(x,7),cat_rotr(x,18)),bitshift(x,-3));
  s1=bitxor(bitxor(cat_rotr(y,17),cat_rotr(y,19)),bitshift(y,-10));
  w(i)=cat_sum(w(i-16),s0,w(i-7),s1);
 end
 a=h(1);b=h(2);c=h(3);d=h(4);e=h(5);f=h(6);g=h(7);v=h(8);
 for i=1:64
  s1=bitxor(bitxor(cat_rotr(e,6),cat_rotr(e,11)),cat_rotr(e,25));
  ch=bitxor(bitand(e,f),bitand(bitcmp(e),g));
  t1=cat_sum(v,s1,ch,k(i),w(i));
  s0=bitxor(bitxor(cat_rotr(a,2),cat_rotr(a,13)),cat_rotr(a,22));
  maj=bitxor(bitxor(bitand(a,b),bitand(a,c)),bitand(b,c));t2=cat_sum(s0,maj);
  v=g;g=f;f=e;e=cat_sum(d,t1);d=c;c=b;b=a;a=cat_sum(t1,t2);
 end
 next=[a;b;c;d;e;f;g;v];for i=1:8,h(i)=cat_sum(h(i),next(i));end
end
id=h(1);
end
function value=cat_rotr(x,n),value=bitor(bitshift(x,-n),bitshift(x,32-n));end
function value=cat_sum(varargin)
 total=uint64(0);for j=1:nargin,total=total+uint64(varargin{j});end
 value=uint32(bitand(total,uint64(4294967295)));
end

% Directional preflight using catalogue metadata only, without local bindings.
function result=compare_catalogues(publisher,consumer,root,required)
try,p=parse_catalogue(publisher);catch,result=compat_diag('INVALID_PUBLISHER_CATALOGUE','','',0,'','',0);return;end
try,c=parse_catalogue(consumer);catch,result=compat_diag('INVALID_CONSUMER_CATALOGUE','','',0,'','',0);return;end
roots=p.names;if ~isempty(root),roots={root};end
checked=containers.Map();
for i=1:numel(roots)
 name=roots{i};
 if ~isKey(p.messages,name)||compat_kind(c,name)==0
  a='';b='';if isKey(p.messages,name),a=name;end;if compat_kind(c,name)~=0,b=name;end
  result=compat_diag('ROOT_UNKNOWN',name,name,0,a,b,0);return;
 end
 result=compat_visit(p,c,name,name,name,0,required,checked);
 if ~result.compatible,return;end
end
result=compat_diag('COMPATIBLE','','',0,'','',0);
end
function result=compat_diag(code,message,path,id,a,b,value)
result=struct('compatible',strcmp(code,'COMPATIBLE'),'code',code,'message',message,'path',path,...
 'field_id',uint32(id),'publisher_type',a,'consumer_type',b,'enum_value',int32(value));
end
function kind=compat_kind(s,name)
kind=0;if isKey(s.messages,name),kind=1;elseif isKey(s.enums,name),kind=2;end
end
function result=compat_visit(p,c,name,message,path,id,required,checked)
result=compat_diag('COMPATIBLE','','',0,'','',0);
if compat_kind(p,name)~=compat_kind(c,name),result=compat_diag('TYPE_KIND_MISMATCH',message,path,id,name,name,0);return;end
if isKey(checked,name),return;end
if isKey(p.enums,name)
 a=p.enums(name);b=c.enums(name);
 missing=find(~ismember(a.values,b.values),1);
 if ~isempty(missing),result=compat_diag('ENUM_VALUE_UNKNOWN',message,path,id,name,name,a.values(missing));return;end
elseif isKey(p.messages,name)
 fields=p.messages(name);local=c.messages(name);j=1;
 for i=1:numel(fields)
  a=fields{i};while j<=numel(local)&&local{j}.id<a.id,j=j+1;end
  if j>numel(local)||local{j}.id~=a.id,continue;end
  b=local{j};at=[path '.' a.name];code='COMPATIBLE';
  if ~strcmp(a.type,b.type),code='FIELD_TYPE_MISMATCH';
  elseif ~isequal(a.dims(:),b.dims(:)),code='FIELD_DIMENSIONS_MISMATCH';
  elseif ~strcmp(cardinality(a.modifier),cardinality(b.modifier)),code='FIELD_CARDINALITY_MISMATCH';end
  if ~strcmp(code,'COMPATIBLE'),result=compat_diag(code,message,at,a.id,a.type,b.type,0);return;end
  result=compat_visit(p,c,a.type,message,at,a.id,required,checked);if ~result.compatible,return;end
 end
 if required
  ids=cellfun(@(f) double(f.id),fields);
  for i=1:numel(local)
   b=local{i};if strcmp(b.modifier,'required')&&~any(ids==double(b.id)),result=compat_diag('REQUIRED_FIELD_MISSING',message,[path '.' b.name],b.id,'',b.type,0);return;end
  end
 end
end
checked(name)=true;
end

function check_unsigned(t,x)
if strncmp(t,'uint',4)&&~isa(x,t)
 if ~isnumeric(x)||any(x(:)<0)||any(x(:)>intmax(t))||any(~isfinite(x(:)))||any(x(:)~=fix(x(:)))
  error('SDL:InvalidValue','unsigned value outside native range');
 end
end
end
